            {post.title}
          </h1>
          <div className="flex flex-wrap items-center gap-4 text-sm text-[var(--sea-ink-soft)]">
            <span>
              Published on{' '}
              {new Date(post.created_at).toLocaleDateString('en-US', {
                year: 'numeric',
                month: 'long',
                day: 'numeric'
              })}
            </span>
            {post.tags.length > 0 && (
              <div className="flex flex-wrap gap-2">
