                    className="rounded-full border border-[var(--chip-line)] bg-[var(--chip-bg)] px-2.5 py-0.5 text-xs font-semibold text-[var(--sea-ink)] no-underline hover:bg-[var(--link-bg-hover)] transition"
                  >
